* { box-sizing: border-box; }

body {
     margin: 0;
     padding: 32px 16px;

    font-family: Arial, "Segoe UI", sans-serif;
    background: #eef2f7;
    display: flex;
    justify-content: center;
}

.the-cv {
    width: min(860px, 100%);
    background: #ffffff;
    border-radius: 12px;
    overflow: hidden;
    box-shadow: 0 14px 34px rgba(0, 0, 0, 0.12);
    display: grid;
    grid-template-columns: 280px 1fr;
}

.cot-trai {
    background: linear-gradient(180deg, #1565C0, #0d3f7a);
    color: #ffffff;
    padding: 28px 22px;
    text-align: center;
}

.avatar {
    width: 110px;
    height: 110px;
    border-radius: 50%;
    margin: 0 auto 14px;
    background: #ffffff;
    color: #1565C0;
    font-size: 38px;
    font-weight: 800;
    display: flex;
    align-items: center;
    justify-content: center;
}

.cot-trai h2 { margin: 0 0 4px; font-size: 20px; }

.cot-trai p     { margin: 0 0 16px; font-size: 13px; opacity: 0.85; }

.cot-trai ul {
    list-style: none;
    padding: 0;
    margin: 16px 0 0;
    font-size: 13px;
    text-align: left;
    line-height: 1.9;
}

.cot-phai { padding: 28px 30px; }

.cot-phai h3 {
    margin: 0 0 8px;
    color: #1565C0;
    font-size: 16px;
    border-bottom: 2px solid #e3ebf5;
    padding-bottom: 6px;
}

.cot-phai p {
    margin: 0 0 16px;
    font-size: 14px;
    line-height: 1.7;
    color: #333333;
}

.ky-nang {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-bottom: 18px;
}

.ky-nang span {
    background: #e3f0ff;
    color: #0d3f7a;

      border-radius: 999px;
      padding: 5px 14px;
      font-size: 13px;
      font-weight: 600;
  }

  .lien-ket a {
      color: #1565C0;
      text-decoration: none;
      font-weight: 600;
  }

  .lien-ket a:hover { text-decoration: underline; }

  @media (max-width: 680px) {
      .the-cv { grid-template-columns: 1fr; }
  }
